code='''def transform(grid):
    n = len(grid)
    sep = next((v for v in range(10) if all(x == v for x in grid[4]) and all(grid[r][4] == v for r in range(n))), None)
    if sep is None:
        sep = max(set(grid[4]), key=grid[4].count)
    tile = 4
    bands = (n + 1) // 5
    nt = (n + 1) // 5
    # Find the single patterned tile outside the left-hand color-key column.
    best = None
    for br in range(bands):
        for bc in range(1, nt):
            vals = [[grid[br*5+r][bc*5+c] for c in range(4)] for r in range(4)]
            colors = {x for row in vals for x in row if x not in (0, sep)}
            if colors:
                score = sum(x in colors for row in vals for x in row)
                if best is None or score > best[0]:
                    best = (score, vals, colors)
    _, vals, colors = best
    stencil = [[int(x in colors) for x in row] for row in vals]
    band_colors = []
    for b in range(bands):
        band_colors.append(next((grid[b*5+r][c] for r in range(4) for c in range(4) if grid[b*5+r][c] not in (0, sep)), 0))
    out = [[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r % 5 == 4 or c % 5 == 4:
                out[r][c] = sep
            elif r % 5 < 4 and c % 5 < 4 and stencil[r%5][c%5]:
                out[r][c] = band_colors[r//5]
    return out
